user_id = #{userId}, study_date = #{studyDate}, total_study_time = #{totalTimeSpent}, tomato_count = #{tomatoTimeSpent}, completed_plans = #{completedPlans}, subject_distribution = #{subjectDistribution}, update_time = #{updateTime},
