limit 7

select 
    study_date as studyDate,
    total_study_time as totalTimeSpent,
    tomato_count as tomatoTimeSpent,
    completed_plans as completedPlans
from study_statistics
where user_id = #{userId}
and study_date >= #{startDate}
and study_date <= #{endDate}
order by study_date asc

select h as hourVal, concat(h, '-', h + 2) as timeSlot, coalesce(sum(tr.tomato_duration), 0) as totalMinutes from tomato_record tr inner join ( select distinct HOUR(start_time) as h from tomato_record where user_id = #{userId} and status = 1
and start_time >= #{startDate}
and start_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
) hours on HOUR(tr.start_time) = hours.h where tr.user_id = #{userId} and tr.status = 1
and tr.start_time >= #{startDate}
and tr.start_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
group by h order by h asc
